using System;using System.Collections.Generic;using System.Data.SQLite;using System.IO;using System.Windows.Forms;using WindowsFormsApp1.Models;
namespace WindowsFormsApp1.Data
{
    public class AdministracaoRepository
    {
        private readonly string cs;
        public AdministracaoRepository(){string p=Path.Combine(Application.StartupPath,"Data");Directory.CreateDirectory(p);cs="Data Source="+Path.Combine(p,"hotel.db")+";Version=3;";using(var c=Abrir())using(var x=c.CreateCommand()){x.CommandText=@"CREATE TABLE IF NOT EXISTS Fornecedores(Id INTEGER PRIMARY KEY AUTOINCREMENT,Nome TEXT NOT NULL,TipoProduto TEXT,ValorProduto NUMERIC,Email TEXT,Telefone TEXT);CREATE TABLE IF NOT EXISTS AchadosPerdidos(Id INTEGER PRIMARY KEY AUTOINCREMENT,Item TEXT NOT NULL,Quarto TEXT,DataEntrada TEXT NOT NULL,Status TEXT NOT NULL);CREATE TABLE IF NOT EXISTS Produtos(Id INTEGER PRIMARY KEY AUTOINCREMENT,Nome TEXT NOT NULL UNIQUE,Preco NUMERIC NOT NULL DEFAULT 0,Estoque INTEGER NOT NULL DEFAULT 0);";x.ExecuteNonQuery();}GarantirCategoria();}
        private SQLiteConnection Abrir(){var c=new SQLiteConnection(cs);c.Open();return c;}
        private void GarantirCategoria(){using(var c=Abrir())using(var q=new SQLiteCommand("PRAGMA table_info(Produtos)",c))using(var r=q.ExecuteReader()){bool existe=false;while(r.Read())if(r["name"].ToString()=="Categoria")existe=true;if(existe)return;}using(var c=Abrir())using(var q=new SQLiteCommand("ALTER TABLE Produtos ADD COLUMN Categoria TEXT",c))q.ExecuteNonQuery();}
        public List<Fornecedor> ListarFornecedores(string busca=""){var l=new List<Fornecedor>();using(var c=Abrir())using(var q=new SQLiteCommand("SELECT * FROM Fornecedores WHERE Nome LIKE @b OR TipoProduto LIKE @b ORDER BY Nome",c)){q.Parameters.AddWithValue("@b","%"+busca+"%");using(var r=q.ExecuteReader())while(r.Read())l.Add(new Fornecedor{Id=Convert.ToInt64(r["Id"]),Nome=r["Nome"].ToString(),TipoProduto=r["TipoProduto"].ToString(),ValorProduto=Convert.ToDecimal(r["ValorProduto"]),Email=r["Email"].ToString(),Telefone=r["Telefone"].ToString()});}return l;}
        public void SalvarFornecedor(Fornecedor f){using(var c=Abrir())using(var q=new SQLiteCommand("INSERT INTO Fornecedores(Nome,TipoProduto,ValorProduto,Email,Telefone) VALUES(@n,@t,@v,@e,@f)",c)){q.Parameters.AddWithValue("@n",f.Nome);q.Parameters.AddWithValue("@t",f.TipoProduto);q.Parameters.AddWithValue("@v",f.ValorProduto);q.Parameters.AddWithValue("@e",f.Email);q.Parameters.AddWithValue("@f",f.Telefone);q.ExecuteNonQuery();}}
        public void ExcluirFornecedor(long id){ExecutarId("DELETE FROM Fornecedores WHERE Id=@id",id);}
        public List<Produto> ListarProdutos(string busca=""){var l=new List<Produto>();using(var c=Abrir())using(var q=new SQLiteCommand("SELECT * FROM Produtos WHERE Nome LIKE @b ORDER BY Nome",c)){q.Parameters.AddWithValue("@b","%"+busca+"%");using(var r=q.ExecuteReader())while(r.Read())l.Add(new Produto{Id=Convert.ToInt64(r["Id"]),Nome=r["Nome"].ToString(),Preco=Convert.ToDecimal(r["Preco"]),Estoque=Convert.ToInt32(r["Estoque"]),Categoria=r["Categoria"].ToString()});}return l;}
        public void SalvarProduto(Produto p){using(var c=Abrir())using(var q=new SQLiteCommand("INSERT INTO Produtos(Nome,Preco,Estoque,Categoria) VALUES(@n,0,@e,@c)",c)){q.Parameters.AddWithValue("@n",p.Nome);q.Parameters.AddWithValue("@e",p.Estoque);q.Parameters.AddWithValue("@c",p.Categoria);q.ExecuteNonQuery();}}
        public void AtualizarProduto(Produto p){using(var c=Abrir())using(var q=new SQLiteCommand("UPDATE Produtos SET Nome=@n,Estoque=@e,Categoria=@c WHERE Id=@id",c)){q.Parameters.AddWithValue("@n",p.Nome);q.Parameters.AddWithValue("@e",p.Estoque);q.Parameters.AddWithValue("@c",p.Categoria);q.Parameters.AddWithValue("@id",p.Id);q.ExecuteNonQuery();}}
        public List<AchadoPerdido> ListarAchados(){var l=new List<AchadoPerdido>();using(var c=Abrir())using(var q=new SQLiteCommand("SELECT * FROM AchadosPerdidos ORDER BY DataEntrada DESC",c))using(var r=q.ExecuteReader())while(r.Read())l.Add(new AchadoPerdido{Id=Convert.ToInt64(r["Id"]),Item=r["Item"].ToString(),Quarto=r["Quarto"].ToString(),DataEntrada=DateTime.Parse(r["DataEntrada"].ToString()),Status=r["Status"].ToString()});return l;}
        public void SalvarAchado(AchadoPerdido a){using(var c=Abrir())using(var q=new SQLiteCommand("INSERT INTO AchadosPerdidos(Item,Quarto,DataEntrada,Status) VALUES(@i,@q,@d,'Guardado')",c)){q.Parameters.AddWithValue("@i",a.Item);q.Parameters.AddWithValue("@q",a.Quarto);q.Parameters.AddWithValue("@d",a.DataEntrada.ToString("s"));q.ExecuteNonQuery();}}
        public void DevolverAchado(long id){using(var c=Abrir())using(var q=new SQLiteCommand("UPDATE AchadosPerdidos SET Status='Devolvido' WHERE Id=@id",c)){q.Parameters.AddWithValue("@id",id);q.ExecuteNonQuery();}}
        private void ExecutarId(string sql,long id){using(var c=Abrir())using(var q=new SQLiteCommand(sql,c)){q.Parameters.AddWithValue("@id",id);q.ExecuteNonQuery();}}
    }
}
